solution:
public class ValidadorPassword {
    static boolean esValida(String password) {
        if (password.length() < 8) return false;
        boolean tieneLetra = false;
        boolean tieneDigito = false;
        for (int i = 0; i < password.length(); i++) {
            char c = password.charAt(i);
            if (Character.isLetter(c)) tieneLetra = true;
            if (Character.isDigit(c)) tieneDigito = true;
        }
        return tieneLetra && tieneDigito;
    }

    public static void main(String[] args) {
        String[] passwords = {"abc12345", "short", "nosingles123"};
        for (String pwd : passwords) {
            if (esValida(pwd)) {
                System.out.println(pwd + " -> Valid");
            } else {
                System.out.println(pwd + " -> Invalid");
            }
        }
    }
}

