solution:
public class ConversorUnidades {
    static double kmAMillas(double km) { return km * 0.621371; }
    static double kgALibras(double kg) { return kg * 2.20462; }
    static double celsiusAFahrenheit(double c) { return (c * 9.0 / 5.0) + 32; }
    static double litrosAGalones(double l) { return l * 0.264172; }

    public static void main(String[] args) {
        System.out.printf("100 km   = %.2f miles%n", kmAMillas(100.0));
        System.out.printf("75 kg    = %.2f pounds%n", kgALibras(75.0));
        System.out.printf("37C      = %.2f F%n", celsiusAFahrenheit(37.0));
        System.out.printf("20 liters= %.2f gallons%n", litrosAGalones(20.0));
    }
}
